const inputItems = $input.all().map(i => i.json || {});

function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v == null) return [];
  return [v];
}

function splitMulti(value) {
  if (Array.isArray(value)) {
    return value.flatMap(v => splitMulti(v)).filter(Boolean);
  }

  return String(value || "")
    .split(/[\n,; ]+/)
    .map(v => v.trim())
    .filter(Boolean);
}

function safeServerName(ip, index = 0) {
  return `target_${String(ip || `unknown_${index + 1}`).replace(/[^A-Za-z0-9]/g, "_")}`;
}

/**
 * รองรับ 3 แบบ:
 * 1) item.body เป็น array จาก Normalize Webhook Body
 * 2) item.body เป็น object หลัง Item Lists split
 * 3) item เป็น object target โดยตรง
 */
const rawJobs = [];

for (const item of inputItems) {
  if (Array.isArray(item.body)) {
    rawJobs.push(...item.body);
  } else if (item.body && typeof item.body === "object") {
    rawJobs.push(item.body);
  } else {
    rawJobs.push(item);
  }
}

if (!rawJobs.length) {
  throw new Error("No Vuls jobs found from input/body.");
}

const targets = [];

rawJobs.forEach((job, jobIndex) => {
  const params = job.parameters || {};

  const ips = splitMulti(
    params.target_ips ||
    params.target_ip ||
    job.target_ips ||
    job.target_ip ||
    job.target
  );

  const users = splitMulti(
    params.ssh_users ||
    params.ssh_user ||
    job.ssh_users ||
    job.ssh_user ||
    job.sshUser ||
    job.username
  );

  const ports = splitMulti(
    params.ssh_ports ||
    params.ssh_port ||
    job.ssh_ports ||
    job.ssh_port ||
    job.sshPort ||
    22
  );

  if (!ips.length) {
    throw new Error(`No target IP found at job index ${jobIndex}`);
  }

  if (!users.length) {
    throw new Error(`No SSH user found at job index ${jobIndex}`);
  }

  ips.forEach((ip, ipIndex) => {
    const sshUser = users.length === 1 ? users[0] : users[ipIndex];
    const sshPort = Number(ports.length === 1 ? ports[0] : ports[ipIndex] || 22);

    if (!sshUser) {
      throw new Error(`No SSH user for target ${ip}`);
    }

    const serverLabel = safeServerName(ip, targets.length);

    targets.push({
      ip,
      target: ip,
      serverLabel,
      serverName: serverLabel,

      sshUser,
      username: sshUser,
      sshPort,

      // ใช้ key กลางบนเครื่อง n8n/Vuls server
      // Execute command จะ map เป็น /tmp/vuls_id_rsa ใน container เอง
      sshKeyPath: null,

      // ถ้าเป็นเครื่องเก่า เช่น metasploitable2 ค่อยเปลี่ยนเป็น true
      legacySsh: Boolean(job.legacySsh || params.legacySsh || false),

      scanJobId: job.scanJobId || null,
      projectId: job.projectId || null,
      callbackUrl: job.callbackUrl || null,
      signature: job.signature || null,

      toolName: "vuls"
    });
  });
});

return [
  {
    json: {
      toolName: "vuls",
      target: targets.length === 1 ? targets[0].ip : "multiple",
      target_ip: targets.map(t => t.ip).join(","),
      sshUser: targets.map(t => t.sshUser).join(","),
      sshPort: targets.length === 1 ? targets[0].sshPort : null,

      // สำคัญ: ส่งหลายเครื่องเข้า Execute command เป็น array เดียว
      targets,

      // เก็บ scanJobId หลายตัวไว้ เผื่อ Code node/HTTP callback ต้องใช้ต่อ
      scanJobs: targets.map(t => ({
        scanJobId: t.scanJobId,
        projectId: t.projectId,
        target: t.ip,
        serverName: t.serverName,
        callbackUrl: t.callbackUrl,
        signature: t.signature
      }))
    }
  }
];

const item = $input.first().json || {};

const stdout = String(item.stdout || "");
const stderr = String(item.stderr || "");

function extractJsonBetweenMarkers(text) {
  const m = text.match(/###VULS_JSON_START###\s*([\s\S]*?)\s*###VULS_JSON_END###/);
  if (!m) return null;

  const raw = m[1].trim();

  try {
    return JSON.parse(raw);
  } catch (e) {
    throw new Error("Cannot parse Vuls JSON payload: " + e.message + "\nRAW:\n" + raw.slice(0, 2000));
  }
}

const payload = extractJsonBetweenMarkers(stdout);

if (!payload) {
  return [
    {
      json: {
        toolName: "vuls",
        status: "failed",
        target: "N/A",
        findings: [],
        hosts: [],
        summary: {
          total: 0,
          critical: 0,
          high: 0,
          medium: 0,
          low: 0,
          info: 1
        },
        severity_mix: [
          { severity: "CRITICAL", count: 0 },
          { severity: "HIGH", count: 0 },
          { severity: "MEDIUM", count: 0 },
          { severity: "LOW", count: 0 },
          { severity: "INFO", count: 1 }
        ],
        error: "No Vuls JSON marker found in Execute a command output",
        meta: {
          stdout: stdout.slice(-12000),
          stderr: stderr.slice(-8000)
        }
      }
    }
  ];
}

const findings = Array.isArray(payload.findings) ? payload.findings : [];

const summary = payload.summary || {
  total: findings.length,
  critical: findings.filter(f => f.severity === "CRITICAL").length,
  high: findings.filter(f => f.severity === "HIGH").length,
  medium: findings.filter(f => f.severity === "MEDIUM").length,
  low: findings.filter(f => f.severity === "LOW").length,
  info: findings.filter(f => f.severity === "INFO").length
};

return [
  {
    json: {
      ...payload,
      findings,
      summary,
      severity_mix: [
        { severity: "CRITICAL", count: Number(summary.critical || 0) },
        { severity: "HIGH", count: Number(summary.high || 0) },
        { severity: "MEDIUM", count: Number(summary.medium || 0) },
        { severity: "LOW", count: Number(summary.low || 0) },
        { severity: "INFO", count: Number(summary.info || 0) }
      ]
    }
  }
];

const input = $input.first().json || {};
const bodyRaw = input.body ?? input;
const body = Array.isArray(bodyRaw) ? (bodyRaw[0] || {}) : bodyRaw;
const params = body.parameters || input.parameters || {};

const targetName =
  params.target_name ||
  params.service_name ||
  params.name ||
  body.targetName ||
  input.targetName ||
  "metlo-target";

let displayTarget = String(
  params.base_url ||
  params.target_api_url ||
  params.target_url ||
  params.url ||
  body.base_url ||
  body.target_url ||
  body.target ||
  input.base_url ||
  input.target_url ||
  input.target ||
  ""
).trim();

if (!displayTarget) {
  throw new Error("Missing target URL for Metlo. Expected target or parameters.target_api_url.");
}

if (!/^https?:\/\//i.test(displayTarget)) {
  displayTarget = "http://" + displayTarget;
}
displayTarget = displayTarget.replace(/\/+$/, "");

// n8n reaches a host-local monitored service through Docker's host alias,
// while the portal keeps showing the URL that the user entered.
const monitoredTarget = displayTarget.replace(
  /^(https?:\/\/)(127\.0\.0\.1|localhost)(?=:|\/|$)/i,
  "$1host.docker.internal"
);

const metloBackendUrl = String(
  params.metlo_backend_url ||
  body.metloBackendUrl ||
  body.metlo_backend_url ||
  input.metloBackendUrl ||
  input.metlo_backend_url ||
  "http://host.docker.internal:8080"
).replace(/\/+$/, "");

return [{
  json: {
    ...body,
    scanJobId: body.scanJobId || input.scanJobId,
    projectId: body.projectId || input.projectId,
    toolName: "metlo",
    target: monitoredTarget,
    displayTarget,
    targetName,
    metloBackendUrl,
    callbackUrl: body.callbackUrl || input.callbackUrl,
    signature: body.signature || input.signature
  }
}];

const payload = $("Prepare Metlo Payload1").first().json || {};
const endpointItems = $("Get Metlo Endpoints").all().map((item) => item.json || {});
const alertItems = $("Get Metlo Alerts").all().map((item) => item.json || {});

const displayTarget = payload.displayTarget || payload.target || "metlo-target";
const monitoredTarget = payload.target || displayTarget;
const scanJobId = payload.scanJobId || null;

function text(value, fallback = "", maxLength = 1500) {
  return String(value ?? fallback).slice(0, maxLength);
}

function hostOf(value) {
  try {
    return new URL(String(value)).host.toLowerCase();
  } catch (error) {
    return String(value || "")
      .replace(/^https?:\/\//i, "")
      .replace(/\/.*$/, "")
      .toLowerCase();
  }
}

function endpointHost(record) {
  return String(record?.host || record?.apiEndpoint?.host || "").toLowerCase();
}

function collect(value, predicate) {
  if (Array.isArray(value)) return value.flatMap((item) => collect(item, predicate));
  if (!value || typeof value !== "object") return [];
  if (predicate(value)) return [value];
  return ["data", "items", "results", "endpoints", "alerts", "topAlerts"]
    .flatMap((key) => collect(value[key], predicate));
}

function isEndpoint(record) {
  return !!(record && record.path && record.method && record.host);
}

function isAlert(record) {
  return !!(record && record.type && (record.apiEndpoint || record.riskScore || record.description));
}

function severityOf(riskScore) {
  const risk = String(riskScore || "").toLowerCase();
  if (risk.includes("critical")) return "CRITICAL";
  if (risk.includes("high")) return "HIGH";
  if (risk.includes("medium") || risk.includes("moderate")) return "MEDIUM";
  if (risk.includes("low")) return "LOW";
  return "INFO";
}

function cvssOf(severity) {
  return ({ CRITICAL: 9.0, HIGH: 7.0, MEDIUM: 5.0, LOW: 2.0, INFO: 0 })[severity];
}

function statusOf(status) {
  const normalized = String(status || "OPEN").toUpperCase();
  if (normalized === "RESOLVED" || normalized === "IGNORED") return normalized;
  return "OPEN";
}

const monitoredHost = hostOf(monitoredTarget);
const endpoints = endpointItems
  .flatMap((item) => collect(item, isEndpoint))
  .filter((endpoint) => endpointHost(endpoint) === monitoredHost);
const alerts = alertItems
  .flatMap((item) => collect(item, isAlert))
  .filter((alert) => !endpointHost(alert) || endpointHost(alert) === monitoredHost);

const uniqueEndpointKeys = new Set();
const observedEndpoints = endpoints.filter((endpoint) => {
  const key = endpoint.uuid || [endpointHost(endpoint), endpoint.method, endpoint.path].join("|");
  if (uniqueEndpointKeys.has(key)) return false;
  uniqueEndpointKeys.add(key);
  return true;
});

const uniqueAlertKeys = new Set();
const activeAlerts = alerts.filter((alert) => {
  const endpoint = alert.apiEndpoint || {};
  const key = alert.uuid || [alert.type, endpointHost(alert), endpoint.method, endpoint.path, alert.createdAt].join("|");
  if (uniqueAlertKeys.has(key)) return false;
  uniqueAlertKeys.add(key);
  return true;
});

function endpointKey(endpoint) {
  return [endpointHost(endpoint), String(endpoint.method || "").toUpperCase(), String(endpoint.path || "")].join("|");
}

const alertsByEndpoint = new Map();
for (const alert of activeAlerts) {
  const endpoint = alert.apiEndpoint || {};
  const key = alert.apiEndpointUuid || endpoint.uuid || endpointKey(endpoint);
  if (!alertsByEndpoint.has(key)) alertsByEndpoint.set(key, []);
  alertsByEndpoint.get(key).push(alert);
}

function matchingAlerts(endpoint) {
  return alertsByEndpoint.get(endpoint.uuid) || alertsByEndpoint.get(endpointKey(endpoint)) || [];
}

const findings = observedEndpoints.map((endpoint) => {
  const method = String(endpoint.method || "API").toUpperCase();
  const path = String(endpoint.path || "unknown endpoint");
  const matchedAlerts = matchingAlerts(endpoint);
  const alert = matchedAlerts[0];
  const severity = alert ? severityOf(alert.riskScore || alert.severity) : "INFO";
  const type = alert ? String(alert.type || "Security Alert") : null;
  const rawDescription = alert?.description ||
    ("Metlo observed API traffic for " + method + " " + path + " on " + displayTarget + ". No security alert is currently attached to this endpoint.");
  const description = String(rawDescription).split(monitoredHost).join(displayTarget);

  return {
    title: alert
      ? text("Metlo Alert - " + type + " - " + method + " " + path, "Metlo Alert", 500)
      : text("Metlo Observed Endpoint - " + method + " " + path, "Metlo Endpoint", 500),
    severity,
    description: text(description, "Metlo observed an API endpoint.", 20000),
    remediation: alert
      ? "Review this detected endpoint and apply suitable authentication, authorization, and data exposure controls."
      : "Review the endpoint inventory and continue monitoring it for security alerts.",
    target: displayTarget,
    status: alert ? statusOf(alert.status) : "OPEN",
    cvss: cvssOf(severity)
  };
});

const observedAlertKeys = new Set(observedEndpoints.flatMap((endpoint) =>
  matchingAlerts(endpoint).map((alert) => alert.uuid || alert.apiEndpointUuid || endpointKey(alert.apiEndpoint || {}))
));

for (const alert of activeAlerts) {
  const key = alert.uuid || alert.apiEndpointUuid || endpointKey(alert.apiEndpoint || {});
  if (observedAlertKeys.has(key)) continue;
  const endpoint = alert.apiEndpoint || {};
  const method = String(endpoint.method || "API").toUpperCase();
  const path = String(endpoint.path || "unknown endpoint");
  const severity = severityOf(alert.riskScore || alert.severity);
  const rawDescription = alert.description || ("Metlo reported an alert for " + method + " " + path + ".");
  findings.push({
    title: text("Metlo Alert - " + String(alert.type || "Security Alert") + " - " + method + " " + path, "Metlo Alert", 500),
    severity,
    description: text(String(rawDescription).split(monitoredHost).join(displayTarget), "Metlo reported a security alert.", 20000),
    remediation: "Investigate this Metlo alert and remediate exposure or controls on the affected API endpoint.",
    target: displayTarget,
    status: statusOf(alert.status),
    cvss: cvssOf(severity)
  });
}

if (findings.length === 0) {
  findings.push({
    title: "Metlo No Traffic Captured - " + displayTarget,
    severity: "INFO",
    description: "Metlo has not received API traffic for " + displayTarget + ". Visiting an endpoint only appears here after the target is connected to a Metlo agent, proxy, or ingestor.",
    remediation: "Connect this API's traffic to Metlo ingestion, then make requests to its endpoints and run this query again.",
    target: displayTarget,
    status: "OPEN",
    cvss: 0
  });
}

function countSeverity(severity) {
  return findings.filter((finding) => finding.severity === severity).length;
}

return [{
  json: {
    toolName: "metlo",
    target: displayTarget,
    status: "completed",
    findings,
    summary: {
      total: findings.length,
      critical: countSeverity("CRITICAL"),
      high: countSeverity("HIGH"),
      medium: countSeverity("MEDIUM"),
      low: countSeverity("LOW"),
      info: countSeverity("INFO")
    },
    meta: {
      tool: "metlo",
      scanJobId,
      targetName: payload.targetName || "metlo-target",
      displayTarget,
      monitoredHost,
      collectionMode: "passive_telemetry",
      generatedTraffic: false,
      observedEndpointCount: observedEndpoints.length,
      alertCount: activeAlerts.length
    }
  }
}];

const input = $input.first().json || {};

// Metlo analyzes traffic already observed by its collector. A portal scan
// should query that telemetry and its alerts, not actively probe the target.
return [{
  json: {
    ...input,
    collectionMode: "passive_telemetry",
    generatedTraffic: false
  }
}];

const input = $input.first().json || {};

// รองรับกรณี body เป็น array จาก Webhook/Switch
const bodyRaw = input.body ?? input;
const body = Array.isArray(bodyRaw) ? (bodyRaw[0] || {}) : bodyRaw;

const parameters = body.parameters || {};

function normalizeTargetType(value, fallbackTarget = "") {
  const v = String(value || "").toLowerCase().trim();

  if (["ip", "single ip", "single_ip"].includes(v)) return "single_ip";
  if (v === "cidr") return "cidr";
  if (["ip range", "ip_range", "range"].includes(v)) return "ip_range";
  if (v === "domain") return "domain";

  const t = String(fallbackTarget || "").trim();

  if (/^\d{1,3}(\.\d{1,3}){3}\s*-\s*\d{1,3}(\.\d{1,3}){3}$/.test(t)) return "ip_range";
  if (/^\d{1,3}(\.\d{1,3}){3}\s*-\s*\d{1,3}$/.test(t)) return "ip_range";
  if (/^\d{1,3}(\.\d{1,3}){3}\/\d{1,2}$/.test(t)) return "cidr";
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(t)) return "single_ip";

  return "domain";
}

function normalizeScanProfile(value) {
  const v = String(value || "").toLowerCase().trim();

  if (v.includes("quick")) return "quick";
  if (v.includes("high")) return "high_risk";
  if (v.includes("all")) return "all_scripts";
  if (v.includes("full")) return "full";
  if (v.includes("agent")) return "agent_only";

  return "quick";
}

// เดา target type ก่อน
const rawTargetType =
  parameters.target_type ||
  parameters.targetType ||
  body.targetType ||
  body.assetType ||
  body.target_type;

// สำคัญ: เลือก target ตามชนิดก่อน ห้ามหยิบ parameters.target ก่อนเสมอ
function pickTargetByType(type) {
  const t = String(type || "").toLowerCase().trim();

  if (["ip_range", "ip range", "range"].includes(t)) {
    return (
      parameters.ip_range ||
      parameters.range ||
      body.ip_range ||
      body.range ||
      parameters.target ||
      parameters.target_ip ||
      body.target ||
      body.target_ip ||
      body.targets?.[0]
    );
  }

  if (t === "cidr") {
    return (
      parameters.cidr ||
      body.cidr ||
      parameters.target ||
      parameters.target_ip ||
      body.target ||
      body.target_ip ||
      body.targets?.[0]
    );
  }

  if (t === "domain") {
    return (
      parameters.domain ||
      body.domain ||
      parameters.target ||
      body.target ||
      body.targets?.[0]
    );
  }

  return (
    parameters.target_ip ||
    parameters.target ||
    body.target_ip ||
    body.target ||
    body.targets?.[0]
  );
}

let target = pickTargetByType(rawTargetType);

if (!target) {
  throw new Error(
    `Missing target. Received body=${JSON.stringify(body).slice(0, 500)}`
  );
}

target = String(target).trim();

const targetType = normalizeTargetType(rawTargetType, target);

const scanProfile = normalizeScanProfile(
  parameters.scan_profile ||
  parameters.scanProfile ||
  body.scanProfile ||
  body.template ||
  "quick"
);

let callbackUrl =
  body.callbackUrl ||
  input.callbackUrl ||
  "http://host.docker.internal:3000/api/scans/callback";

if (callbackUrl.includes("localhost:3000")) {
  callbackUrl = callbackUrl.replace("localhost", "host.docker.internal");
}

return [
  {
    json: {
      scanJobId: body.scanJobId,
      projectId: body.projectId,
      toolName: "sirius",

      target,
      targetType,
      scanProfile,
      priority: Number(body.priority || parameters.priority || 3),

      callbackUrl,
      signature: body.signature,
      netraSignature: input.headers?.["x-netra-signature"],

      siriusBaseUrl: "http://sirius-api:9001",

      originalBody: body
    }
  }
];

const contextItems = $input.all().map(item => item.json || {});

const preparedFallback = $("Prepare Sirius Payload1").first().json || {};
const firstContext = contextItems[0] || {};

const requestedTarget =
  firstContext.target ||
  preparedFallback.target ||
  "N/A";

const targetType =
  firstContext.originalTargetType ||
  firstContext.targetType ||
  preparedFallback.targetType ||
  "single_ip";

const scanJobId =
  firstContext.scanJobId ||
  preparedFallback.scanJobId;

const projectId =
  firstContext.projectId ||
  preparedFallback.projectId;

const scanProfile =
  firstContext.scanProfile ||
  preparedFallback.scanProfile;

const inputItems = contextItems;

function ipToInt(ip) {
  const parts = String(ip).trim().split(".").map(Number);
  if (parts.length !== 4 || parts.some(n => Number.isNaN(n) || n < 0 || n > 255)) return null;
  return (((parts[0] << 24) >>> 0) + (parts[1] << 16) + (parts[2] << 8) + parts[3]) >>> 0;
}

function isIpInRange(ip, range) {
  const [start, endRaw] = String(range).split("-").map(s => s.trim());
  if (!start || !endRaw) return false;

  let end = endRaw;

  // รองรับ 192.168.87.130-139
  if (!end.includes(".")) {
    const p = start.split(".");
    if (p.length === 4) {
      end = `${p[0]}.${p[1]}.${p[2]}.${end}`;
    }
  }

  const n = ipToInt(ip);
  const a = ipToInt(start);
  const b = ipToInt(end);

  if (n === null || a === null || b === null) return false;
  return n >= Math.min(a, b) && n <= Math.max(a, b);
}

function isIpInCidr(ip, cidr) {
  const [base, maskText] = String(cidr).split("/");
  const mask = Number(maskText);
  const n = ipToInt(ip);
  const b = ipToInt(base);

  if (n === null || b === null || Number.isNaN(mask) || mask < 0 || mask > 32) return false;

  const m = mask === 0 ? 0 : (0xffffffff << (32 - mask)) >>> 0;
  return (n & m) === (b & m);
}

function pickHost(v) {
  return (
    v.host_ip ||
    v.hostIp ||
    v.ip ||
    v.target ||
    v.host ||
    v.hostname ||
    v.asset_ip ||
    v.assetIp ||
    v.node_ip ||
    ""
  );
}

function hasRealHost(v) {
  return String(pickHost(v) || "").trim() !== "";
}

function matchesTargetScope(v) {
  const host = String(pickHost(v) || v.__sourceTarget || "").trim();
  const hostname = String(v.hostname || v.host || v.name || "").trim();

  // สำคัญ:
  // /host/vulnerabilities/all ของ Sirius มักคืน CVE aggregate ไม่มี host/ip
  // ถ้าไม่มี host ห้าม filter ทิ้ง ไม่งั้นจะเหลือ 0 finding
  if (!host) return true;

  if (targetType === "single_ip") {
    return host === requestedTarget;
  }

  if (targetType === "ip_range") {
    return isIpInRange(host, requestedTarget);
  }

  if (targetType === "cidr") {
    return isIpInCidr(host, requestedTarget);
  }

  if (targetType === "domain") {
    return host.includes(requestedTarget) || hostname.includes(requestedTarget);
  }

  return true;
}

function pickId(v, index) {
  return (
    v.vid ||
    v.cve ||
    v.cveId ||
    v.cve_id ||
    v.id ||
    v.cveID ||
    v.name ||
    v.title ||
    `SIRIUS-FINDING-${index + 1}`
  );
}

function pickCvssScore(v) {
  const candidates = [
    v.cvss,
    v.cvssScore,
    v.cvss_score,
    v.baseScore,
    v.base_score,
    v.cvssV3,
    v.cvss_v3,
    v.cvssV2,
    v.cvss_v2,
    v.cvss3,
    v.cvss2,

    v.riskScore?.CVSSV3?.cvssV3?.baseScore,
    v.riskScore?.CVSSV2?.cvssV2?.baseScore,
    v.risk_score?.CVSSV3?.cvssV3?.baseScore,
    v.risk_score?.CVSSV2?.cvssV2?.baseScore,

    v.cvssData?.baseScore,
    v.metrics?.cvssMetricV31?.[0]?.cvssData?.baseScore,
    v.metrics?.cvssMetricV30?.[0]?.cvssData?.baseScore,
    v.metrics?.cvssMetricV2?.[0]?.cvssData?.baseScore
  ];

  for (const value of candidates) {
    const n = Number(value);
    if (!Number.isNaN(n) && n >= 0 && n <= 10) return n;
  }

  return null;
}

function pickRiskScore(v) {
  const candidates = [
    v.riskScore,
    v.risk_score,
    v.score,
    v.risk
  ];

  for (const value of candidates) {
    if (typeof value === "object") continue;

    const n = Number(value);
    if (!Number.isNaN(n)) return n;
  }

  return null;
}

function normalizeSeverityText(value) {
  const s = String(value || "").toUpperCase().trim();

  if (["CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO"].includes(s)) return s;

  if (["INFORMATIONAL", "INFORMATIVE"].includes(s)) return "INFO";
  if (["IMPORTANT"].includes(s)) return "HIGH";
  if (["MODERATE"].includes(s)) return "MEDIUM";
  if (["NEGLIGIBLE", "UNKNOWN", "NONE"].includes(s)) return "INFO";

  return "";
}

function severityFromCvss(score) {
  const n = Number(score);

  if (Number.isNaN(n) || n <= 0) return "INFO";
  if (n >= 9.0) return "CRITICAL";
  if (n >= 7.0) return "HIGH";
  if (n >= 4.0) return "MEDIUM";
  return "LOW";
}

function severityFromSiriusRiskScore(score) {
  const n = Number(score);

  if (Number.isNaN(n)) return "INFO";

  // fallback เท่านั้น ไม่ใช่สูตรที่ตรง Sirius UI 100%
  // เพราะ riskScore ของ /host/vulnerabilities/all ไม่ได้แยก critical/info เหมือน UI
  if (n >= 5) return "HIGH";
  if (n >= 4) return "MEDIUM";
  if (n >= 2) return "LOW";
  return "INFO";
}

function pickSeverity(v) {
  const explicitCandidates = [
    v.severity,
    v.baseSeverity,
    v.base_severity,
    v.cvssSeverity,
    v.cvss_severity,
    v.riskLevel,
    v.risk_level,
    v.level,
    v.priority,

    v.riskScore?.CVSSV3?.cvssV3?.baseSeverity,
    v.riskScore?.CVSSV2?.severity,
    v.risk_score?.CVSSV3?.cvssV3?.baseSeverity,
    v.risk_score?.CVSSV2?.severity,

    v.metrics?.cvssMetricV31?.[0]?.cvssData?.baseSeverity,
    v.metrics?.cvssMetricV30?.[0]?.cvssData?.baseSeverity,
    v.metrics?.cvssMetricV2?.[0]?.baseSeverity
  ];

  for (const value of explicitCandidates) {
    const normalized = normalizeSeverityText(value);
    if (normalized) return normalized;
  }

  const cvss = pickCvssScore(v);
  if (cvss !== null) return severityFromCvss(cvss);

  const riskScore = pickRiskScore(v);
  return severityFromSiriusRiskScore(riskScore);
}

function pickDisplayScore(v) {
  const cvss = pickCvssScore(v);
  if (cvss !== null) return cvss;

  const riskScore = pickRiskScore(v);
  if (riskScore !== null) return riskScore;

  return 0;
}

function safeText(value, fallback = "", max = 1500) {
  return String(value ?? fallback).slice(0, max);
}

function extractVulnerabilities(obj) {
  if (!obj || typeof obj !== "object") return [];

  const sourceTarget =
    obj.target ||
    obj.ip ||
    obj.host_ip ||
    obj.hostIp ||
    obj.hostname ||
    obj.host?.ip ||
    obj.host?.host ||
    obj.host?.hostname ||
    obj.data?.target ||
    obj.data?.ip ||
    obj.data?.host ||
    obj.data?.hostname ||
    requestedTarget;

  function attachSource(arr) {
    return arr
      .filter(v => v && typeof v === "object")
      .map(v => ({
        ...v,
        __sourceTarget: pickHost(v) || sourceTarget
      }));
  }

  if (Array.isArray(obj)) return obj.flatMap(hostItem => extractVulnerabilities(hostItem));
  if (Array.isArray(obj.data)) return attachSource(obj.data);
  if (Array.isArray(obj.vulnerabilities)) return attachSource(obj.vulnerabilities);
  if (Array.isArray(obj.cves)) return attachSource(obj.cves);
  if (Array.isArray(obj.results)) return attachSource(obj.results);
  if (Array.isArray(obj.items)) return attachSource(obj.items);
  if (obj.vid || obj.cve || obj.cveId || obj.cve_id || obj.cveID) return attachSource([obj]);

  const host = obj.host || obj.data || obj;

  const hostIp =
    obj.ip ||
    obj.target ||
    obj.host_ip ||
    obj.hostIp ||
    host.ip ||
    host.host_ip ||
    host.hostIp ||
    host.host ||
    host.hostname ||
    sourceTarget;

  if (Array.isArray(host.vulnerabilities)) {
    return host.vulnerabilities.map(v => ({
      ...v,
      __sourceTarget: pickHost(v) || hostIp
    }));
  }

  if (Array.isArray(host.cves)) {
    return host.cves.map(v => ({
      ...v,
      __sourceTarget: pickHost(v) || hostIp
    }));
  }

  return [];
}

let rawVulnerabilities = [];

for (const item of inputItems) {
  rawVulnerabilities.push(...extractVulnerabilities(item));
}

// กรณี /host/vulnerabilities/all คืนหลาย item ตรง ๆ เช่น 330 items
if (!rawVulnerabilities.length && inputItems.length > 1) {
  rawVulnerabilities = inputItems.filter(v => v && typeof v === "object");
}

// filter ตาม target type เฉพาะกรณี record มี host จริง
const scopedVulnerabilities = rawVulnerabilities.filter(matchesTargetScope);

// ไม่ dedupe เพื่อให้จำนวนตรงกับ Sirius UI
const uniqueVulns = scopedVulnerabilities.filter(v => v && typeof v === "object");

let findings = uniqueVulns.map((v, index) => {
  const id = pickId(v, index);
  const score = pickDisplayScore(v);
  const severity = pickSeverity(v);

  const host =
    pickHost(v) ||
    v.__sourceTarget ||
    requestedTarget;

  return {
    title: safeText(v.title || v.name || id, id, 200),
    severity,
    description: safeText(
      v.description ||
      v.desc ||
      v.summary ||
      `Sirius detected vulnerability ${id}.`,
      `Sirius detected vulnerability ${id}.`,
      1500
    ),
    remediation: safeText(
      v.remediation ||
      v.solution ||
      v.fix ||
      "Review the affected service/package and apply vendor-recommended updates or mitigations.",
      "Review the affected service/package and apply vendor-recommended updates or mitigations.",
      1000
    ),
    target: safeText(host, requestedTarget, 200),
    status: "OPEN",
    cvss: score,
    tool: "sirius"
  };
});

if (!findings.length) {
  findings = [
    {
      title: "Sirius Scan Completed",
      severity: "INFO",
      description:
        "Sirius scan completed or aggregate endpoint was queried, but no vulnerability records were returned.",
      remediation:
        "Check Sirius UI, selected scan profile, target type, agent availability, and whether /host/vulnerabilities/all contains records.",
      target: requestedTarget,
      status: "OPEN",
      cvss: 0,
      tool: "sirius"
    }
  ];
}

const summary = {
  total: findings.length,
  returned: findings.length,
  critical: findings.filter(f => f.severity === "CRITICAL").length,
  high: findings.filter(f => f.severity === "HIGH").length,
  medium: findings.filter(f => f.severity === "MEDIUM").length,
  low: findings.filter(f => f.severity === "LOW").length,
  info: findings.filter(f => f.severity === "INFO").length
};

const hosts = [...new Set(findings.map(f => f.target))]
  .filter(Boolean)
  .map(ip => ({
    ip,
    total: findings.filter(f => f.target === ip).length,
    critical: findings.filter(f => f.target === ip && f.severity === "CRITICAL").length,
    high: findings.filter(f => f.target === ip && f.severity === "HIGH").length,
    medium: findings.filter(f => f.target === ip && f.severity === "MEDIUM").length,
    low: findings.filter(f => f.target === ip && f.severity === "LOW").length,
    info: findings.filter(f => f.target === ip && f.severity === "INFO").length
  }));

return [
  {
    json: {
      scanJobId,
      projectId,
      toolName: "sirius",
      target: requestedTarget,
      targetType,
      status: "completed",

      findings: findings.map(f => ({
        title: String(f.title || "Unknown Sirius Finding").slice(0, 200),
        severity: String(f.severity || "INFO").toUpperCase(),
        description: String(
          f.description || "Sirius detected a vulnerability on the target."
        ).slice(0, 1500),
        remediation: String(
          f.remediation || "Review the affected service/package and apply vendor-recommended updates or mitigations."
        ).slice(0, 1000),
        target: String(f.target || requestedTarget || "N/A").slice(0, 200),
        status: String(f.status || "OPEN").toUpperCase(),
        cvss: Number(f.cvss || 0),
        tool: "sirius"
      })),

      summary,

      meta: {
        tool: "sirius",
        requestedTarget,
        targetType,
        scanProfile,
        sourceEndpoint: "/host",
        beforeFilterCount: rawVulnerabilities.length,
        afterScopeFilterCount: scopedVulnerabilities.length,
        afterDedupeCount: uniqueVulns.length,
        hasHostField: rawVulnerabilities.some(hasRealHost),
        hosts
      }
    }
  }
];

const prepared = $("Prepare Sirius Payload1").first().json || {};

if (!prepared.target) {
  throw new Error(
    `Prepare Queue Error: missing prepared.target. prepared=${JSON.stringify(prepared).slice(0, 800)}`
  );
}

const target = String(prepared.target).trim();
const originalTargetType = String(prepared.targetType || "single_ip").trim();

// ถ้า target ถูก split มาเป็น IP เดี่ยวแล้ว ถึง request เดิมจะเป็น ip_range
// ตอนส่งเข้า Sirius ต้องใช้ single_ip
function isSingleIp(value) {
  return /^\d{1,3}(\.\d{1,3}){3}$/.test(String(value || "").trim());
}

function isCidr(value) {
  return /^\d{1,3}(\.\d{1,3}){3}\/\d{1,2}$/.test(String(value || "").trim());
}

function isRange(value) {
  return String(value || "").includes("-");
}

function isDomain(value) {
  const v = String(value || "").trim();
  return v && !isSingleIp(v) && !isCidr(v) && !isRange(v);
}

let siriusTargetType = originalTargetType;

if (isSingleIp(target)) {
  siriusTargetType = "single_ip";
} else if (isCidr(target)) {
  siriusTargetType = "cidr";
} else if (isRange(target)) {
  siriusTargetType = "ip_range";
} else if (isDomain(target)) {
  siriusTargetType = "domain";
}

if (!["single_ip", "cidr", "ip_range", "domain"].includes(siriusTargetType)) {
  throw new Error(`Prepare Queue Error: invalid siriusTargetType=${siriusTargetType}`);
}

const safeId =
  prepared.scanJobId && String(prepared.scanJobId).startsWith("scan-")
    ? prepared.scanJobId
    : `scan-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;

return [
  {
    json: {
      id: safeId,

      targets: [
        {
          value: target,
          type: siriusTargetType
        }
      ],

      options: {
        template_id: prepared.scanProfile || "quick"
      },

      priority: Number(prepared.priority || 3),

      meta: {
        portalScanJobId: prepared.scanJobId,
        projectId: prepared.projectId,
        toolName: "sirius",

        // target จริงที่ส่งให้ Sirius
        target,

        // type จริงที่ Sirius ควรใช้
        targetType: siriusTargetType,

        // type เดิมจาก portal เช่น ip_range
        originalTargetType,

        scanProfile: prepared.scanProfile || "quick"
      }
    }
  }
];

const waitItems = $input.all();
const preparedItems = $("Prepare Sirius Payload1").all().map(i => i.json || {});

return waitItems.map((item, index) => {
  const prepared = preparedItems[index] || {};

  return {
    json: {
      ...item.json,

      scanJobId: prepared.scanJobId,
      projectId: prepared.projectId,
      toolName: prepared.toolName || "sirius",

      target: prepared.target,
      targetType: prepared.targetType,
      originalTargetType:
        prepared.originalBody?.parameters?.target_type ||
        prepared.targetType ||
        "single_ip",

      scanProfile: prepared.scanProfile,
      callbackUrl: prepared.callbackUrl,
      signature: prepared.signature,
      netraSignature: prepared.netraSignature,
      siriusBaseUrl: prepared.siriusBaseUrl || "http://sirius-api:9001"
    }
  };
});

const input = $input.first().json || {};
const rawBody = input.body ?? input;
const bodyItems = Array.isArray(rawBody) ? rawBody : [rawBody];

function clone(obj) {
  return JSON.parse(JSON.stringify(obj || {}));
}

function splitMulti(value, splitSpace = false) {
  if (Array.isArray(value)) {
    return value.flatMap(v => splitMulti(v, splitSpace));
  }

  const regex = splitSpace ? /[\n,; ]+/ : /[\n,;]+/;

  return String(value || "")
    .split(regex)
    .map(v => v.trim())
    .filter(Boolean);
}

function getToolName(item) {
  return String(
    item?.toolName ||
    item?.parameters?.toolName ||
    input?.toolName ||
    ""
  ).toLowerCase().trim();
}

function getTargets(item) {
  const p = item?.parameters || {};

  return splitMulti(
    p.target_ips ||
    p.target_ip ||
    item?.target_ips ||
    item?.target_ip ||
    item?.target,
    true
  );
}

function getUsers(item) {
  const p = item?.parameters || {};

  return splitMulti(
    p.ssh_users ||
    p.ssh_user ||
    item?.ssh_users ||
    item?.ssh_user ||
    item?.sshUser ||
    item?.username,
    false
  );
}

function getPorts(item) {
  const p = item?.parameters || {};

  return splitMulti(
    p.ssh_ports ||
    p.ssh_port ||
    p.sshPort ||
    item?.ssh_ports ||
    item?.ssh_port ||
    item?.sshPort ||
    22,
    false
  );
}

function toPort(value) {
  const n = Number(value || 22);
  return Number.isFinite(n) && n > 0 ? n : 22;
}

function safeServerName(ip, index = 0) {
  return `target_${String(ip || `unknown_${index + 1}`).replace(/[^A-Za-z0-9]/g, "_")}`;
}

function makeVulsItem(originalItem, target, user, port, index) {
  const out = clone(originalItem);
  out.parameters = out.parameters || {};

  out.toolName = "vuls";

  out.target = target;
  out.target_ip = target;
  delete out.target_ips;

  out.parameters.target_ip = target;
  delete out.parameters.target_ips;

  out.ssh_user = user;
  out.sshUser = user;
  out.username = user;

  out.parameters.ssh_user = user;
  delete out.parameters.ssh_users;

  out.ssh_port = port;
  out.sshPort = port;
  out.parameters.ssh_port = port;

  const serverLabel = safeServerName(target, index);

  out.serverLabel = serverLabel;
  out.serverName = serverLabel;
  out.ip = target;

  // สำคัญ: ห้ามบังคับใช้ scanJobId เดียวกันทุก IP
  // ให้เก็บ scanJobId / signature ของ item นั้น ๆ
  out.scanJobId = originalItem.scanJobId || out.scanJobId || null;
  out.projectId = originalItem.projectId || out.projectId || null;
  out.callbackUrl = originalItem.callbackUrl || out.callbackUrl || null;
  out.signature = originalItem.signature || out.signature || null;

  return out;
}

// ถ้าไม่ใช่ Vuls ให้ปล่อยผ่านเหมือนเดิม เพื่อไม่กระทบ tool อื่น
const hasVuls = bodyItems.some(item => getToolName(item) === "vuls");

if (!hasVuls) {
  return [
    {
      json: input
    }
  ];
}

const normalizedBody = [];

// เก็บ users/ports แบบ global เผื่อ body ถูก split target มาแล้ว
let globalUsers = [];
let globalPorts = [];

for (const item of bodyItems) {
  if (getToolName(item) !== "vuls") continue;

  const users = getUsers(item);
  const ports = getPorts(item);

  if (users.length > globalUsers.length) {
    globalUsers = users;
  }

  if (ports.length > globalPorts.length) {
    globalPorts = ports;
  }
}

for (const itemIndex in bodyItems) {
  const item = bodyItems[itemIndex];

  if (getToolName(item) !== "vuls") {
    normalizedBody.push(item);
    continue;
  }

  const targets = getTargets(item);
  const users = getUsers(item);
  const ports = getPorts(item);

  if (!targets.length) {
    throw new Error("Vuls: missing target IP");
  }

  // กรณี body ถูก split มาแล้ว:
  // item 1 target เดียว แต่ ssh_user ยังเป็นหลายบรรทัดเหมือนกันทุก item
  if (bodyItems.length > 1 && targets.length === 1) {
    const target = targets[0];

    const user =
      globalUsers.length > 1
        ? globalUsers[Number(itemIndex)]
        : users[0] || globalUsers[0];

    const port =
      globalPorts.length > 1
        ? toPort(globalPorts[Number(itemIndex)])
        : toPort(ports[0] || globalPorts[0] || 22);

    if (!user) {
      throw new Error(
        `Vuls: target ${target} has no matching ssh_user at item index ${itemIndex}`
      );
    }

    normalizedBody.push(makeVulsItem(item, target, user, port, Number(itemIndex)));
    continue;
  }

  // กรณี body ยังไม่ถูก split: target/user หลายบรรทัดอยู่ใน item เดียว
  if (!users.length) {
    throw new Error("Vuls: missing ssh_user");
  }

  if (users.length !== 1 && users.length !== targets.length) {
    throw new Error(
      `Vuls: number of ssh_user must be 1 or equal to number of targets. targets=${targets.length}, users=${users.length}`
    );
  }

  if (ports.length !== 1 && ports.length !== targets.length) {
    throw new Error(
      `Vuls: number of ssh_port must be 1 or equal to number of targets. targets=${targets.length}, ports=${ports.length}`
    );
  }

  targets.forEach((target, index) => {
    const user = users.length === 1 ? users[0] : users[index];
    const port = toPort(ports.length === 1 ? ports[0] : ports[index]);

    normalizedBody.push(makeVulsItem(item, target, user, port, index));
  });
}

const batchTarget = normalizedBody.map(item => item.target).join(",");
const batchUsers = normalizedBody.map(item => item.ssh_user).join(",");
const batchPorts = normalizedBody.map(item => item.ssh_port).join(",");
const firstTarget = normalizedBody[0];

// Keep Vuls multi-host scans as one loop item. Item Lists1 will split body
// once, while Prepare Vuls Payload expands the comma-delimited hosts again.
return [
  {
    json: {
      ...input,
      body: [
        {
          ...firstTarget,
          target: batchTarget,
          target_ip: batchTarget,
          ip: batchTarget,
          ssh_user: batchUsers,
          sshUser: batchUsers,
          username: batchUsers,
          ssh_port: batchPorts,
          sshPort: batchPorts,
          parameters: {
            ...(firstTarget.parameters || {}),
            target_ip: batchTarget,
            ssh_user: batchUsers,
            ssh_port: batchPorts
          }
        }
      ],
      toolName: "vuls",
      target: batchTarget,
      target_ip: batchTarget,
      ssh_user: batchUsers
    }
  }
];

const ctx = $json || {};

return [
  {
    json: {
      scanJobId: ctx.scanJobId,
      projectId: ctx.projectId,
      toolName: "sirius",
      target: ctx.target || ctx.ip || "N/A",
      targetType: ctx.targetType || ctx.originalTargetType || "single_ip",
      status: "completed",

      findings: [],

      summary: {
        total: 0,
        returned: 0,
        critical: 0,
        high: 0,
        medium: 0,
        low: 0,
        info: 0
      },

      meta: {
        tool: "sirius",
        ignored: true,
        reason:
          ctx.error?.message ||
          ctx.message ||
          "No Sirius vulnerabilities for this host",
        target: ctx.target || ctx.ip || "N/A"
      }
    }
  }
];
